"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["65958"],{2620(e){e.exports=JSON.parse('{"id":"F110","slug":"life-insurance-need","name":"Life Insurance Needs Analysis","subject":"Personal Finance","section":"Personal Finance","topic":"Insurance: life, health, property, disability","level":"Intermediate","aliases":["insurance","income replacement","DIME method","human life value"],"formula":{"latex":"\\\\text{Need}=C\\\\,\\\\frac{1-\\\\left(\\\\frac{1+g}{1+r}\\\\right)^{n}}{r-g}+\\\\text{Debts}+\\\\text{Goals}-\\\\text{Assets}","also":[],"text":"Cover needed = present value of the income to replace (first-year amount, growing at g, discounted at r for n years) + debts to clear + future goals (such as education) - existing assets and cover"},"symbols":[{"symbol":"C","meaning":"First-year income to replace = income x replacement share","unit":"money"},{"symbol":"g","meaning":"Yearly growth in that income (inflation)","unit":"per year"},{"symbol":"r","meaning":"Rate you could earn investing the payout","unit":"per year"},{"symbol":"n","meaning":"Years the family needs support","unit":"years"}],"when_to_use":"Use it to size life insurance for people who depend on your income. It is a needs method: it asks what the family would need, not a multiple of salary. A negative result means existing assets already cover the need. The discount rate matters a lot, so test a lower one for caution. It ignores taxes and any survivor benefits, so treat it as an estimate.","worked_example":{"problem":"Income is 60,000. The family needs 70% of it for 20 years, growing 3% a year, and the payout could earn 5%. Debts to clear are 180,000, education goals 100,000, and existing assets and cover total 150,000.","inputs":{"y":60000,"rp":70,"n":20,"g":3,"r":5,"debts":180000,"goals":100000,"assets":150000},"steps":[{"label":"First-year income to replace","working":"60000 x 0.7","value":"42,000.00"},{"label":"Present value of the support","working":"42000 / (0.05-0.03) x (1-((1+0.03) / (1+0.05))^20)","value":"670,520.91"},{"label":"Existing assets and cover","working":"150000","value":"150,000.00"},{"label":"Cover needed = PV + debts + goals - assets","working":"max(670521+180000+100000-150000, 0)","value":"800,520.91"},{"label":"Rule of thumb: 10 x income","working":"10 x 60000","value":"600,000.00"}],"answer":"The first-year income to replace is 42,000.00, with a present value of 670,520.91 over 20 years. Adding debts and goals and subtracting 150,000.00 of existing assets gives a cover need of 800,520.91. A single-multiple rule of 10 times income would give 600,000.00."},"calculator":{"available":true,"inputs":[{"id":"y","label":"Annual income","unit":"money","type":"number","default":60000,"hint":""},{"id":"rp","label":"Share of income to replace","unit":"%","type":"number","default":70,"hint":""},{"id":"n","label":"Years of support","unit":"years","type":"number","default":20,"hint":"","min":1},{"id":"g","label":"Income growth (inflation)","unit":"%","type":"number","default":3,"hint":""},{"id":"r","label":"Return on the payout","unit":"%","type":"number","default":5,"hint":""},{"id":"debts","label":"Debts to clear","unit":"money","type":"number","default":180000,"hint":""},{"id":"goals","label":"Future goals","unit":"money","type":"number","default":100000,"hint":""},{"id":"assets","label":"Existing assets and cover","unit":"money","type":"number","default":150000,"hint":""}],"checks":[{"expr":"r!=g and y>0","message":"The return and the growth rate must differ, and income must be above zero."}],"steps":[{"id":"c","label":"First-year income to replace","expr":"y*rp","format":"money"},{"id":"pv","label":"Present value of the support","expr":"c/(r-g)*(1-((1+g)/(1+r))^n)","format":"money"},{"id":"assets_","label":"Existing assets and cover","expr":"assets","format":"money"},{"id":"need","label":"Cover needed = PV + debts + goals - assets","expr":"max(pv+debts+goals-assets, 0)","format":"money"},{"id":"rule","label":"Rule of thumb: 10 x income","expr":"10*y","format":"money"}],"results":["pv","need"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"c":42000,"pv":670520.9085840895,"assets_":150000,"need":800520.9085840895,"rule":600000}},"finder":{"finds":"How much life cover a family needs","needs":"Income, years of support, debts, goals, existing assets"},"related":[{"slug":"pv-growing-annuity","name":"Present Value of a Growing Annuity"},{"slug":"disability-coverage-gap","name":"Disability Insurance Income Gap"},{"slug":"estate-tax-basic","name":"Estate Tax Estimate"}],"related_ids":["F017","F108","F121"],"group":"Personal finance","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Need</mtext><mo>=</mo><mi>C</mi><mtext>\u2009</mtext><mfrac><mrow><mn>1</mn><mo>\u2212</mo><msup><mrow><mo fence=\\"true\\">(</mo><mfrac><mrow><mn>1</mn><mo>+</mo><mi>g</mi></mrow><mrow><mn>1</mn><mo>+</mo><mi>r</mi></mrow></mfrac><mo fence=\\"true\\">)</mo></mrow><mi>n</mi></msup></mrow><mrow><mi>r</mi><mo>\u2212</mo><mi>g</mi></mrow></mfrac><mo>+</mo><mtext>Debts</mtext><mo>+</mo><mtext>Goals</mtext><mo>\u2212</mo><mtext>Assets</mtext></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Need}=C\\\\,\\\\frac{1-\\\\left(\\\\frac{1+g}{1+r}\\\\right)^{n}}{r-g}+\\\\text{Debts}+\\\\text{Goals}-\\\\text{Assets}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"lc-discounting-cost","name":"Letter of Credit and Discounting: All-In Cost"},"next":{"slug":"arbitrage-holding-cost","name":"Limits to Arbitrage: Holding Cost and Adverse Move"},"lesson":null,"total":522}')}}]);